CREATE TABLE `changelog_entries` (
	`id` text PRIMARY KEY NOT NULL,
	`slug` text NOT NULL,
	`status` text DEFAULT 'draft' NOT NULL,
	`version` text NOT NULL,
	`product` text NOT NULL,
	`channel` text NOT NULL,
	`published_at` text NOT NULL,
	`content_json` text NOT NULL,
	`revision` integer DEFAULT 1 NOT NULL,
	`updated_by_token_id` text,
	`created_at` integer DEFAULT (unixepoch() * 1000) NOT NULL,
	`updated_at` integer DEFAULT (unixepoch() * 1000) NOT NULL,
	CONSTRAINT "changelog_status_check" CHECK("changelog_entries"."status" in ('draft','published')),
	CONSTRAINT "changelog_channel_check" CHECK("changelog_entries"."channel" in ('preview','release')),
	CONSTRAINT "changelog_revision_check" CHECK("changelog_entries"."revision" > 0),
	CONSTRAINT "changelog_content_check" CHECK(json_valid("changelog_entries"."content_json"))
);
--> statement-breakpoint
CREATE UNIQUE INDEX `changelog_entries_slug_unique` ON `changelog_entries` (`slug`);--> statement-breakpoint
CREATE INDEX `changelog_publication_idx` ON `changelog_entries` (`status`,`published_at`,`slug`);

-- One-time backfill. Public pages read D1; future editorial changes use the operations API.
--> statement-breakpoint
INSERT INTO changelog_entries (id,slug,status,version,product,channel,published_at,content_json) VALUES ('5675b871-e094-53c9-a1ed-e5caf86e5939','hub-cli-0-1-2-preview-5','published','0.1.2-preview.5','Hub CLI','preview','2026-09-05','{"en":{"title":"A more capable, more reliable Hub operator","description":"Hub CLI 0.1.2-preview.5 introduces autonomous operations guidance, preflight checks, resumable run records, and clearer network and write results.","sections":[{"id":"autonomous-operations","title":"Room for the operator to make decisions","paragraphs":["Version 7 of the operations guidance gives the agent a clear goal: improve the Hub. It can research the ecosystem, find and assess new plugins, or enrich existing listings according to what the site needs.","The operator can choose its priorities, order of work, and workload. The guidance no longer prescribes a fixed quota or a mandatory sequence of steps for every run."]},{"id":"reliable-runs","title":"Better checks before work, clearer records afterward","items":["Preflight checks help confirm the installed CLI, authentication, and service readiness before operations begin.","Structured command contracts make required inputs and supported operations easier for agents to discover.","Run ownership and local checkpoints preserve context when an operation is interrupted."]},{"id":"clearer-failures","title":"Make failures actionable","items":["Network handling distinguishes Cloudflare challenges from service errors and reports request or response-body timeouts.","Interrupted batches distinguish confirmed writes, uncertain outcomes, and items that were never attempted, helping the operator decide what to verify before retrying.","Credential handling supports subsequent processes in unattended environments with a constrained fallback when secure storage does not persist credentials."]},{"id":"availability","title":"Available on the preview channel","paragraphs":["This release is published as @becomeopc/dshx-hub-cli@0.1.2-preview.5 on npm. It includes the version 7 operations guidance. The stable latest channel remains on 0.1.1.","The published package was installed into a fresh environment and checked in separate processes, including the bundled operations guidance and command behavior."]}],"links":[{"label":"Hub CLI 0.1.2-preview.5 on npm","href":"https://www.npmjs.com/package/@becomeopc/dshx-hub-cli/v/0.1.2-preview.5"},{"label":"Release commit on GitHub","href":"https://github.com/liyown/dshx/commit/5660fbc61227d7d8d4b1e8272f9d8e6e42241cf9"}]},"zh":{"title":"让 Hub 运营更自主，也更可靠","description":"Hub CLI 0.1.2-preview.5 带来自主运营规则、运行预检与断点记录，并改进网络错误识别和批量写入结果反馈。","sections":[{"id":"autonomous-operations","title":"让运营 Agent 自己判断下一步","paragraphs":["第 7 版运营规则把目标明确为持续改善 Hub。Agent 可以研究插件生态、寻找并评估新插件，也可以根据网站现状补充已有插件的信息。","运营 Agent 可以自主安排优先级、执行顺序和工作量。每轮运营不再要求完成固定配额，也不再强制经过同一套步骤。"]},{"id":"reliable-runs","title":"开始前有预检，中断后有记录","items":["运行预检用于确认当前 CLI 版本、身份认证和服务就绪状态，尽早发现执行条件不满足的问题。","结构化命令契约列出支持的操作与输入要求，方便 Agent 正确使用工具。","运行归属与本地断点保留执行上下文，帮助恢复被中断的工作。"]},{"id":"clearer-failures","title":"失败时，知道发生了什么","items":["区分 Cloudflare 挑战、服务错误与请求或响应读取超时，让后续处理更有依据。","批量操作中断后，分别记录已确认写入、结果不确定和未尝试的项目，便于先核对再决定是否重试。","改进无人值守环境下的凭据持久化；安全存储未能保留凭据时，可在受限条件下使用备用存储。"]},{"id":"availability","title":"已发布至 preview 通道","paragraphs":["本次 npm 版本为 @becomeopc/dshx-hub-cli@0.1.2-preview.5，内置第 7 版运营规则。稳定通道 latest 仍为 0.1.1。","公开发布的包已完成全新安装与独立进程验证，覆盖内置运营规则与命令行为。"]}],"links":[{"label":"npm 上的 Hub CLI 0.1.2-preview.5","href":"https://www.npmjs.com/package/@becomeopc/dshx-hub-cli/v/0.1.2-preview.5"},{"label":"GitHub 发布提交","href":"https://github.com/liyown/dshx/commit/5660fbc61227d7d8d4b1e8272f9d8e6e42241cf9"}]}}') ON CONFLICT(slug) DO NOTHING;
--> statement-breakpoint
INSERT INTO changelog_entries (id,slug,status,version,product,channel,published_at,content_json) VALUES ('09ccdb72-9e4c-551f-9515-785848a99d13','dshx-0-1-1','published','0.1.1','DSHX · create-dshx','release','2026-08-22','{"en":{"title":"Clearer versions, aligned project templates","description":"DSHX 0.1.1 reports the installed CLI version and keeps create-dshx templates aligned with the framework package for a consistent starting point.","sections":[{"id":"version-reporting","title":"Know which version is installed","paragraphs":["The dshx --version command now reports the version of the installed DSHX package. This makes it easier to identify the environment when sharing diagnostics or comparing local setups."]},{"id":"aligned-templates","title":"Start from a consistent template","paragraphs":["create-dshx and @becomeopc/dshx keep their template versions aligned. Newly generated projects start with the corresponding framework version, reducing confusion between the scaffolding tool and the package used by the project."]}],"links":[{"label":"DSHX 0.1.1 on npm","href":"https://www.npmjs.com/package/@becomeopc/dshx/v/0.1.1"},{"label":"Source changelog","href":"https://github.com/liyown/dshx/blob/5660fbc61227d7d8d4b1e8272f9d8e6e42241cf9/CHANGELOG.md#011---2026-08-22"}]},"zh":{"title":"版本信息更清晰，项目模板保持一致","description":"DSHX 0.1.1 修正 CLI 版本展示，让 create-dshx 项目模板与框架包版本保持一致，便于确认开发环境和排查问题。","sections":[{"id":"version-reporting","title":"准确确认已安装的版本","paragraphs":["dshx --version 现在展示实际安装的 DSHX 包版本。在分享诊断信息或对比不同开发环境时，可以据此确认使用的工具版本。"]},{"id":"aligned-templates","title":"从一致的项目模板开始","paragraphs":["create-dshx 与 @becomeopc/dshx 的模板版本保持同步。新生成的插件项目使用对应的框架版本，减少创建工具与项目依赖之间的版本混淆。"]}],"links":[{"label":"npm 上的 DSHX 0.1.1","href":"https://www.npmjs.com/package/@becomeopc/dshx/v/0.1.1"},{"label":"仓库版本记录","href":"https://github.com/liyown/dshx/blob/5660fbc61227d7d8d4b1e8272f9d8e6e42241cf9/CHANGELOG.md#011---2026-08-22"}]}}') ON CONFLICT(slug) DO NOTHING;
--> statement-breakpoint
INSERT INTO changelog_entries (id,slug,status,version,product,channel,published_at,content_json) VALUES ('f90551f3-f87e-58e2-bc1b-c7d239498a6b','dshx-0-1-0','published','0.1.0','DSHX · create-dshx','release','2026-08-22','{"en":{"title":"Introducing DSHX for DeepSeek Harness plugins","description":"The first public release of DSHX and create-dshx brings TypeScript and React plugin tooling, local development, diagnostics, scaffolding, and runtime inspection.","sections":[{"id":"first-release","title":"A toolkit for plugin authors","paragraphs":["DSHX and create-dshx are available publicly for the first time. DSHX provides build-time tooling for DeepSeek Harness plugins, including TypeScript Host code and React Client interfaces for the protocol-1 generation."]},{"id":"development-workflow","title":"From a new project to a running plugin","items":["Build, check, repair, develop, and inspect plugins with the dshx CLI.","Generate UI, tool, and hook source files with dry-run output, repeatable edits, and rollback support.","Inspect Slots, Tools, Services, and Events through the Host-owned runtime bridge.","Repair plugin manifests deterministically, then validate the result and roll back if validation fails."]},{"id":"runtime-verification","title":"Verified in the actual runtime","paragraphs":["The release was verified with DeepSeek Harness 0.1.0-rc.8 and 0.1.1-rc.2 using the Phase A fixture, including browser rendering and Client hot module replacement. These checks describe the tested versions at the time of release."]}],"links":[{"label":"DSHX 0.1.0 on npm","href":"https://www.npmjs.com/package/@becomeopc/dshx/v/0.1.0"},{"label":"Source changelog","href":"https://github.com/liyown/dshx/blob/5660fbc61227d7d8d4b1e8272f9d8e6e42241cf9/CHANGELOG.md#010---2026-08-22"}]},"zh":{"title":"DSHX 首次发布：为 DeepSeek Harness 开发插件","description":"DSHX 与 create-dshx 首次公开发布，提供 TypeScript、React 插件开发工具，以及本地开发、构建检查、代码生成和运行时 Inspect。","sections":[{"id":"first-release","title":"面向插件作者的开发工具","paragraphs":["DSHX 与 create-dshx 首次公开发布。DSHX 为 DeepSeek Harness 插件提供构建时工具，支持 protocol-1 协议下的 TypeScript Host 代码与 React Client 界面。"]},{"id":"development-workflow","title":"从创建项目到运行插件","items":["通过 dshx CLI 完成构建、检查、修复、本地开发与 Inspect。","生成 UI、tool 和 hook 源码，支持预览改动、可重复执行与失败回滚。","通过 Host 持有的桥接能力，检查运行时的 Slots、Tools、Services 和 Events。","确定性修复插件清单，修复后再次验证，验证失败时回滚。"]},{"id":"runtime-verification","title":"在真实运行环境中验证","paragraphs":["发布时已通过 Phase A fixture 在 DeepSeek Harness 0.1.0-rc.8 与 0.1.1-rc.2 上完成验证，覆盖浏览器渲染与 Client 热更新。这些版本代表本次发布时实际测试过的环境。"]}],"links":[{"label":"npm 上的 DSHX 0.1.0","href":"https://www.npmjs.com/package/@becomeopc/dshx/v/0.1.0"},{"label":"仓库版本记录","href":"https://github.com/liyown/dshx/blob/5660fbc61227d7d8d4b1e8272f9d8e6e42241cf9/CHANGELOG.md#010---2026-08-22"}]}}') ON CONFLICT(slug) DO NOTHING;
